/**
 * views/lesson.js — Screen 3 (plan3 §3 + §10). Section order:
 * The idea → What your notes say (exact excerpt, "From your notes") →
 * What's missing → "What would you do?" scenarios → Pin for revision.
 * No trace table, no plot, no narration, no "Generated by …" meta line,
 * no Got it / Still lost. The hero (gradient descent) lesson renders the
 * two curated scenarios from demo/numopt.scenarios.json — Scenario A opens
 * with no choice selected; picking a choice reveals its supplied reason;
 * "Reveal explanation" shows the recommended reasoning without a choice;
 * "Next scenario" moves to Scenario B and focuses its heading; "Back to
 * scenario 1" restores. Choices are PAGE STATE ONLY — never persisted.
 * Other topics: idea + "What to remember" card + optional reviewed
 * question, marked "Vertex explanation" where added.
 */
import { ROUTES } from '../contracts.js';
import { icon, renderConceptSketch } from '../render.js';

function isGradientDescent(topic) {
  return typeof topic.name === 'string' && /gradient\s+descent/i.test(topic.name);
}

function choiceHighlight(choiceText) {
  const t = String(choiceText || '').toLowerCase();
  if (/larger|longer|bigger/.test(t)) return 'long';
  if (/reduce|smaller|shorter|small/.test(t)) return 'short';
  return null;
}

export async function render(container, ctx, topicId) {
  const { h, state, actions } = ctx;
  const nb = state.notebook;
  const topic = nb.topics.find((t) => t && t.id === topicId);
  if (!topic) return; // route guard already handles this; belt + braces

  /* ---- top bar ---- */
  const back = h('button', { type: 'button', class: 'btn btn-ghost btn-sm', text: '← Coverage map' });
  back.addEventListener('click', () => ctx.navigate(ROUTES.MAP));
  container.appendChild(h('div', { class: 'lesson-topbar' }, [back]));

  /* ---- curated scenarios (page state only, plan3 §10) ---- */
  await actions.loadScenarios();
  const scenarios = actions.scenariosForTopic(topic);
  const isHero = !!scenarios && isGradientDescent(topic);

  const lesson = topic.lesson;
  const cov = (topic.coverage && topic.coverage.status) || 'not_found';
  const chunks = (nb.notes && nb.notes.chunks) || [];
  const cited = (cov === 'not_found' ? [] : (topic.coverage.chunkIds || [])
    .map((id) => chunks.find((c) => c && c.id === id)).filter(Boolean));

  /* ---- live path: lesson not prepared yet ---- */
  if (!lesson && !isHero) {
    const err = state.lessonErrors[topic.id];
    const card = h('article', { class: 'card lesson-card' }, [
      h('h1', { class: 'lesson-title', text: topic.name }),
    ]);
    if (err && err.kind) {
      card.setAttribute('role', 'alert');
      card.appendChild(h('p', { text: err.message || ctx.describeError(err) }));
      if (err.kind === 'no_key') card.appendChild(h('p', { class: 'muted', text: 'Add a BharatCode key to use your notes, or try the demo.' }));
    } else if (state.generating[topic.id]) {
      card.appendChild(h('p', { class: 'muted', text: 'Preparing this lesson — model calls can take up to a minute.' }));
    } else {
      card.appendChild(h('p', { class: 'muted', text: 'No explanation prepared for this topic yet. On the live path, lessons are prepared from your notes on demand.' }));
    }
    const row = h('div', { class: 'btn-row' });
    if (!(state.generating[topic.id] && !err)) {
      const gen = h('button', { type: 'button', class: 'btn btn-primary', text: err && err.kind ? 'Retry' : 'Prepare this lesson' });
      gen.addEventListener('click', () => actions.generateLesson(topic.id, {}));
      row.appendChild(gen);
    }
    if (err && err.kind) {
      const gearBtn = h('button', { type: 'button', class: 'btn btn-ghost', text: 'Open settings' });
      gearBtn.addEventListener('click', actions.openSettings);
      row.appendChild(gearBtn);
    }
    card.appendChild(row);
    container.appendChild(card);
    return;
  }

  const ideaText = lesson && (lesson.idea || lesson.oneLiner || lesson.why)
    || (isHero ? 'Gradient descent walks downhill: each step moves against the local gradient, scaled by the learning rate.' : '');
  const gaps = lesson && Array.isArray(lesson.notesGaps) ? lesson.notesGaps.filter(Boolean) : [];
  const takeaway = lesson && (lesson.takeaway
    || (scenarios && scenarios.length ? (scenarios[scenarios.length - 1].takeaway || scenarios[0].takeaway) : null))
    || (lesson && lesson.oneLiner) || '';
  const distinction = lesson && lesson.distinction
    || (lesson && Array.isArray(lesson.pitfalls) && lesson.pitfalls.length
      ? (lesson.pitfalls[0].text || String(lesson.pitfalls[0])) : '');

  const card = h('article', { class: 'card lesson-card', 'aria-labelledby': 'lesson-heading' });
  card.appendChild(h('h1', { class: 'lesson-title', id: 'lesson-heading', text: topic.name }));

  const vertexTag = () => h('span', { class: 'tag tag-vertex', text: 'Vertex explanation' });
  const notesTag = () => h('span', { class: 'tag tag-notes', text: 'From your notes' });
  const section = (title, extra, bodyChildren) => {
    const s = h('section', { class: 'lesson-section' }, [
      h('h2', { class: 'section-title', text: title }),
      extra || null,
    ].concat(bodyChildren));
    return s;
  };

  /* ---- 1. The idea ---- */
  card.appendChild(section('The idea', isHero || cov !== 'covered' ? vertexTag() : null, [
    h('p', { class: 'idea-text', text: ideaText }),
  ]));

  /* ---- 2. What your notes say ---- */
  const notesBody = [];
  if (cited.length) {
    for (const c of cited) notesBody.push(h('blockquote', { class: 'excerpt-text' }, [h('p', { text: c.text })]));
  } else {
    notesBody.push(h('p', { class: 'row-absent', text: 'No matching passage in these notes.' }));
  }
  card.appendChild(section('What your notes say', cited.length ? notesTag() : null, notesBody));

  /* ---- 3. What's missing ---- */
  if (gaps.length || cov !== 'covered') {
    const missing = gaps.length ? gaps : ['Your notes stop before the decision this topic turns on — read on.'];
    const ul = h('ul', { class: 'gaps-list' });
    for (const g of missing) ul.appendChild(h('li', { text: g }));
    card.appendChild(section("What's missing", vertexTag(), [ul]));
  }

  /* ---- 4a. Hero: "What would you do?" scenarios ---- */
  if (isHero) {
    const wrap = h('section', { class: 'lesson-section scenarios-section', 'aria-label': 'What would you do?' });
    wrap.appendChild(h('h2', { class: 'section-title', text: 'What would you do?' }));
    const slot = h('div', { class: 'scenario-slot' });
    wrap.appendChild(slot);
    card.appendChild(wrap);

    // PAGE STATE ONLY — never persisted, never affects coverage/pins/export.
    const selectedByScenario = new Map();
    const revealedDirect = new Set();
    let current = 0;

    function renderScenario(focusHeading) {
      const sc = scenarios[current];
      if (!sc) return;
      slot.replaceChildren();

      const scCard = h('div', { class: 'scenario-card' });
      const heading = h('h3', { class: 'scenario-title', tabindex: '-1', text: sc.heading || sc.title || ('Scenario ' + (current + 1)) });
      scCard.appendChild(heading);
      if (sc.setup) scCard.appendChild(h('p', { class: 'scenario-setup' }, [h('strong', { text: 'Setup: ' }), sc.setup]));
      if (sc.prompt) scCard.appendChild(h('p', { class: 'scenario-prompt', text: sc.prompt }));

      const wantsSketch = !!sc.visual;
      const visual = sc.visual && typeof sc.visual === 'object' ? sc.visual : {};
      const sketchBox = h('div', { class: 'scenario-sketch' });
      if (wantsSketch) renderConceptSketch(sketchBox, { highlight: null, caption: visual.label, alt: visual.screenReaderSummary });

      const rightCol = h('div', { class: 'scenario-right' });
      const choicesWrap = h('div', { class: 'choice-list', role: 'group', 'aria-label': 'Your options' });
      const revealPanel = h('div', { class: 'reveal-panel', hidden: true, role: 'status', 'aria-live': 'polite' });

      function choiceText(choice) { return choice.label || choice.text || ''; }

      function updateReveal() {
        const chosenId = selectedByScenario.get(sc.id || String(current));
        revealPanel.replaceChildren();
        if (chosenId) {
          const choice = (sc.choices || []).find((c) => c.id === chosenId);
          if (choice) {
            revealPanel.appendChild(h('p', { class: 'reveal-label', text: 'Why: ' }));
            revealPanel.appendChild(h('p', { class: 'reveal-text', text: String(choice.reveal || '') }));
            revealPanel.hidden = false;
          }
        } else if (revealedDirect.has(sc.id || String(current))) {
          const recommendedChoice = (sc.choices || []).find((c) => c && c.recommended);
          const recommended = sc.recommended
            || (recommendedChoice && recommendedChoice.reveal)
            || sc.takeaway
            || (sc.choices && sc.choices[0] && sc.choices[0].reveal)
            || '';
          revealPanel.appendChild(h('p', { class: 'reveal-label', text: 'The reasoning: ' }));
          revealPanel.appendChild(h('p', { class: 'reveal-text', text: String(recommended) }));
          revealPanel.hidden = false;
        } else {
          revealPanel.hidden = true;
        }
        if (wantsSketch) {
          const chosen = (sc.choices || []).find((c) => c.id === chosenId);
          renderConceptSketch(sketchBox, {
            highlight: chosen ? choiceHighlight(choiceText(chosen)) : null,
            caption: visual.label,
            alt: visual.screenReaderSummary,
          });
        }
      }

      (sc.choices || []).forEach((choice) => {
        const already = selectedByScenario.get(sc.id || String(current)) === choice.id;
        const btn = h('button', {
          type: 'button', class: 'choice-btn' + (already ? ' is-selected' : ''),
          'aria-pressed': String(already), text: choiceText(choice),
        });
        btn.addEventListener('click', () => {
          const key = sc.id || String(current);
          const prev = selectedByScenario.get(key);
          if (prev === choice.id) {
            selectedByScenario.delete(key); // clicking the selected choice clears it
          } else {
            selectedByScenario.set(key, choice.id);
            revealedDirect.delete(key); // a choice now carries the explanation
          }
          for (const [i, el] of choicesWrap.querySelectorAll('.choice-btn').entries()) {
            el.classList.toggle('is-selected', selectedByScenario.get(key) === (sc.choices[i] || {}).id);
            el.setAttribute('aria-pressed', selectedByScenario.get(key) === (sc.choices[i] || {}).id ? 'true' : 'false');
          }
          updateReveal();
        });
        choicesWrap.appendChild(btn);
      });
      rightCol.appendChild(choicesWrap);

      const revealBtn = h('button', { type: 'button', class: 'btn btn-ghost btn-sm reveal-btn', text: 'Reveal explanation' });
      revealBtn.addEventListener('click', () => {
        revealedDirect.add(sc.id || String(current));
        updateReveal();
      });
      rightCol.appendChild(revealBtn);
      rightCol.appendChild(revealPanel);

      if (wantsSketch) {
        const split = h('div', { class: 'scenario-split' }, [sketchBox, rightCol]);
        scCard.appendChild(split);
      } else {
        scCard.appendChild(rightCol);
      }

      const navRow = h('div', { class: 'btn-row scenario-nav' });
      if (current < scenarios.length - 1) {
        const next = h('button', { type: 'button', class: 'btn btn-primary btn-sm', text: 'Next scenario' });
        next.addEventListener('click', () => {
          current += 1;
          renderScenario(true);
        });
        navRow.appendChild(next);
      }
      if (current > 0) {
        const prevBtn = h('button', { type: 'button', class: 'btn btn-ghost btn-sm', text: 'Back to scenario 1' });
        prevBtn.addEventListener('click', () => {
          current = 0;
          renderScenario(true);
        });
        navRow.appendChild(prevBtn);
      }
      scCard.appendChild(navRow);
      slot.appendChild(scCard);
      updateReveal();
      if (focusHeading) heading.focus(); // focus only on user-driven scenario switches
    }
    renderScenario(false);
  } else {
    /* ---- 4b. Other topics: What to remember + optional reviewed question ---- */
    if (takeaway || distinction) {
      const remember = h('div', { class: 'remember-card' }, [
        h('h3', { class: 'sub-title', text: 'What to remember' }),
        takeaway ? h('p', { class: 'remember-takeaway', text: takeaway }) : null,
        distinction ? h('p', { class: 'remember-distinction' }, [h('strong', { text: 'Key distinction: ' }), distinction]) : null,
        vertexTag(),
      ]);
      card.appendChild(remember);
    }
    if (lesson.examQuestion && lesson.examQuestion.q) {
      const eq = lesson.examQuestion;
      const answer = h('div', { class: 'exam-answer', hidden: true });
      if (eq.modelAnswer) await ctx.rmd(answer, eq.modelAnswer);
      const reveal = h('button', { type: 'button', class: 'btn btn-ghost btn-sm', 'aria-expanded': 'false', text: 'Reveal reviewed answer' });
      reveal.addEventListener('click', () => {
        const open = answer.hidden;
        answer.hidden = !open;
        reveal.setAttribute('aria-expanded', String(open));
        reveal.textContent = open ? 'Hide reviewed answer' : 'Reveal reviewed answer';
      });
      card.appendChild(section('Question to revisit', null, [
        h('p', { class: 'exam-q', text: eq.q }),
        eq.source === 'vertex' ? vertexTag() : null,
        reveal,
        answer,
      ]));
    }
    if (!scenarios && isGradientDescent(topic)) {
      card.appendChild(h('p', { class: 'muted scenarios-unavailable', text: 'The curated scenarios are unavailable in this build.' }));
    }
  }

  /* ---- 5. Pin for revision ---- */
  const pinSection = h('section', { class: 'lesson-section pin-section', 'aria-label': 'Pin for revision' });
  const initialPinned = actions.getPins().includes(topic.id);
  const pinBtn = h('button', {
    type: 'button', class: 'btn btn-pin',
    'aria-pressed': String(initialPinned),
  }, [icon(initialPinned ? 'pinned' : 'pin'), h('span', { text: initialPinned ? 'Pinned for revision' : 'Pin for revision' })]);
  pinBtn.addEventListener('click', async () => {
    const pins = await actions.pinToggle(topic.id);
    const pinned = pins.includes(topic.id);
    pinBtn.setAttribute('aria-pressed', String(pinned));
    pinBtn.replaceChildren(icon(pinned ? 'pinned' : 'pin'), h('span', { text: pinned ? 'Pinned for revision' : 'Pin for revision' }));
    ctx.announce(pinned ? 'Added to revision sheet' : 'Removed from revision sheet');
    sheetLink.textContent = 'View revision sheet (' + pins.length + ')';
  });
  pinSection.appendChild(h('h2', { class: 'section-title', text: 'Pin for revision' }));
  pinSection.appendChild(pinBtn);
  const sheetLink = h('a', { class: 'accent-link sheet-link', href: ROUTES.SHEET, text: 'View revision sheet (' + actions.getPins().length + ')' });
  pinSection.appendChild(sheetLink);
  card.appendChild(pinSection);

  container.appendChild(card);
}
